const url = $json.target_url || $('Set Firecrawl URL').first().json.target_url || '';
return [{ json: {
  url: url,
  formats: ['markdown'],
  onlyMainContent: true,
  onlyCleanContent: false,
  removeBase64Images: true,
  blockAds: true,
  timeout: 60000,
  storeInCache: true
}}];

const resp = $json;
const cfg = $('Set Firecrawl URL').first().json;
const targetUrl = cfg.target_url || '';
const now = new Date().toISOString();
function cap(s, n) { return (s == null ? '' : String(s)).substring(0, n); }

function technicalErrorRow(errSummary, preview) {
  return [{ json: {
    created_at: now, source_type: 'scraped_web', platform: 'website', source_url: targetUrl, parsed_at: now,
    published_at: '', freshness_status: 'unknown', entity_type: 'irrelevant', company_name: '', profile_name: '',
    profile_url: '', region: '', service_type: 'unknown', offer_text: '', terms: '', contact_public: '',
    text_context: '', detected_need: '', competitor_strength: 1, lead_signal_score: 1, content_idea_score: 1,
    quality_score: 1, reason: '', recommended_action: 'ignore', status: 'skipped',
    processing_status: 'technical_error', parse_method: 'firecrawl_error',
    parse_error: cap('Firecrawl scrape failed: ' + errSummary, 800),
    raw_response_preview: cap(preview, 500), route: 'technical_errors', needs_manual_review: true,
    repair_used: false, repair_status: ''
  }}];
}

const apiError = (resp == null) || resp.error || resp.success === false || (resp.code && resp.code >= 400) || (resp.statusCode && resp.statusCode >= 400);
if (apiError) {
  const summary = cap(JSON.stringify((resp && (resp.error || resp.message || resp.code || resp.statusCode)) || 'unknown error'), 300);
  return technicalErrorRow(summary, cap(JSON.stringify(resp), 500));
}

const data = resp.data || resp;
let markdown = (resp.data && resp.data.markdown) || resp.markdown || (data && data.markdown) || (resp.data && resp.data.data && resp.data.data.markdown) || '';
const metadata = (resp.data && resp.data.metadata) || resp.metadata || (data && data.metadata) || {};
markdown = String(markdown).replace(/\r/g, '').replace(/\n{3,}/g, '\n\n').trim();
const meaningful = markdown.replace(/[#>*_|]/g, '').replace(/\s+/g, ' ').trim();
if (!markdown || meaningful.length < 80) {
  return technicalErrorRow('scrape succeeded but markdown empty/unusable (' + meaningful.length + ' meaningful chars)', cap(markdown || JSON.stringify(metadata), 500));
}

const sourceUrl = metadata.sourceURL || metadata.url || targetUrl;
const title = metadata.title || '';
const description = metadata.description || '';

return [{ json: {
  route: '', source_type: 'scraped_web', platform: 'website', source_url: sourceUrl, profile_url: '',
  published_at: '', parsed_at: now, text_context: cap(markdown, 6000),
  page_title: cap(title, 300), page_description: cap(description, 500)
}}];

const response = $json;
const srcRecord = $('Normalize Firecrawl Output').first().json;
function cap(s, n) { return (s == null ? '' : String(s)).substring(0, n); }

// Handle HTTP error responses — preserve everything
if (response.error || response.status >= 400) {
  const err = 'Primary HTTP error: ' + cap(JSON.stringify(response.error || response.status), 300);
  const prev = cap(JSON.stringify(response), 500);
  return [{ json: {
    parse_ok: false, parse_method: 'primary_json', repair_used: false,
    processing_status: 'technical_error_candidate',
    primary_parse_error: err,
    primary_raw_response_preview: prev,
    content_summary: 'http_error',
    parse_error: err,
    raw_response_preview: prev,
    original_record: srcRecord
  }}];
}

// Find text item
let textItem;
let contentSummary = '';
try {
  if (!response.content || !Array.isArray(response.content)) throw new Error('no content array');
  contentSummary = response.content.map(c => c.type).join(',');
  textItem = response.content.find(c => c.type === 'text');
} catch(e) {
  const err = 'Primary parse failed: no content array: ' + e.message;
  const prev = cap(JSON.stringify(response), 500);
  return [{ json: {
    parse_ok: false, parse_method: 'primary_json', repair_used: false,
    processing_status: 'technical_error_candidate',
    primary_parse_error: err,
    primary_raw_response_preview: prev,
    content_summary: 'no_content_array',
    parse_error: err,
    raw_response_preview: prev,
    original_record: srcRecord
  }}];
}

if (!textItem || !textItem.text) {
  const err = 'Primary parse failed: no text item';
  const prev = cap(JSON.stringify(response.content || response), 500);
  return [{ json: {
    parse_ok: false, parse_method: 'primary_json', repair_used: false,
    processing_status: 'technical_error_candidate',
    primary_parse_error: err,
    primary_raw_response_preview: prev,
    content_summary: contentSummary || 'no_text_item',
    parse_error: err,
    raw_response_preview: prev,
    original_record: srcRecord
  }}];
}

const rawPreview = cap(textItem.text, 500);

// Parse with defensive cleanup
let parsed;
let candidate = '';
try {
  let txt = textItem.text.trim();
  txt = txt.replace(/^```json\s*/i, '').replace(/\s*```$/,'').trim();
  txt = txt.replace(/^```\s*/,'').replace(/\s*```$/,'').trim();
  const bStart = txt.indexOf('{');
  const bEnd = txt.lastIndexOf('}');
  if (bStart !== -1 && bEnd !== -1) txt = txt.substring(bStart, bEnd + 1);
  candidate = txt;
  txt = txt.replace(/[‘’]/g, "'").replace(/[“”«»]/g, '"');
  parsed = JSON.parse(txt);
} catch(e) {
  const err = 'Primary JSON parse failed: ' + e.message;
  const prev = cap(candidate || rawPreview, 500);
  return [{ json: {
    parse_ok: false, parse_method: 'primary_json', repair_used: false,
    processing_status: 'technical_error_candidate',
    primary_parse_error: err,
    primary_raw_response_preview: prev,
    content_summary: 'text_present_json_invalid',
    parse_error: err,
    raw_response_preview: prev,
    original_record: srcRecord
  }}];
}

return [{ json: {
  parse_ok: true,
  parse_method: 'primary_json',
  repair_used: false,
  repair_status: '',
  parse_error: '',
  raw_response_preview: rawPreview,
  ...parsed
}}];

const input = $json;
const srcRecord = $('Normalize Firecrawl Output').first().json;
function cap(s, n) { return (s == null ? '' : String(s)).substring(0, n); }

const rawPreview = cap(input.primary_raw_response_preview || input.raw_response_preview || 'empty', 500);
const primaryErr = cap(input.primary_parse_error || input.parse_error || 'Primary parse failed', 300);

const repairSystem = `You are a JSON repair formatter, not a market analyst. Convert the raw response into strict JSON. Do not invent facts. If raw response is unusable, return an object that can be routed to technical_errors.
Return JSON only. No markdown. First char {, last char }.
Fields: created_at, source_type, platform, source_url, parsed_at, published_at, freshness_status, entity_type, company_name, profile_name, profile_url, region, service_type, offer_text, terms, contact_public, text_context, detected_need, competitor_strength, lead_signal_score, content_idea_score, quality_score, reason, recommended_action, status.
Unknown text -> "". Unknown score -> 1. Unusable -> status=skipped, entity_type=irrelevant, recommended_action=ignore, all scores=1.
Enums: entity_type[competitor,lead_signal,market_signal,content_idea,irrelevant]; recommended_action[monitor,contact,create_content,ignore,investigate]; status[analyzed,skipped]; freshness_status[fresh,recent,old,unknown].`;

const userMsg = JSON.stringify({
  original_record: {
    source_type: srcRecord.source_type || '',
    platform: srcRecord.platform || '',
    source_url: srcRecord.source_url || '',
    profile_url: srcRecord.profile_url || '',
    parsed_at: srcRecord.parsed_at || '',
    published_at: srcRecord.published_at || '',
    text_context: cap(srcRecord.text_context || '', 500)
  },
  raw_primary_response: rawPreview,
  primary_parse_error: primaryErr
});

return [{ json: {
  model: 'claude-sonnet-4-6',
  max_tokens: 700,
  temperature: 0,
  system: repairSystem,
  messages: [{ role: 'user', content: userMsg }]
}}];

const response = $json;
const primary = $('Parse Primary JSON').first().json;
function cap(s, n) { return (s == null ? '' : String(s)).substring(0, n); }

const primaryErr = cap(primary.primary_parse_error || primary.parse_error || 'unknown', 300);
const primaryPreview = cap(primary.primary_raw_response_preview || primary.raw_response_preview || '', 500);

function technicalError(repairErr) {
  const combined = cap('Primary: ' + primaryErr + ' | Repair: ' + repairErr, 800);
  // preserve primary raw preview first; append repair error only if space allows
  let preview = primaryPreview;
  if (preview.length < 440) {
    preview = cap(preview + ' || REPAIR_ERR: ' + repairErr, 500);
  }
  return [{ json: {
    parse_ok: false,
    parse_method: 'technical_error',
    repair_used: true,
    repair_status: 'failed',
    processing_status: 'technical_error',
    route: 'technical_errors',
    needs_manual_review: true,
    parse_error: combined,
    raw_response_preview: cap(preview, 500),
    original_record: primary.original_record || {}
  }}];
}

// Handle HTTP error from repair call
if (response.error || response.status >= 400) {
  return technicalError('Repair HTTP error: ' + cap(JSON.stringify(response.error || response.status), 300));
}

let textItem;
try {
  textItem = (response.content || []).find(c => c.type === 'text');
} catch(e) { textItem = null; }

if (!textItem || !textItem.text) {
  return technicalError('No text item in repair response');
}

const rawPreview = cap(textItem.text, 500);

let parsed;
try {
  let txt = textItem.text.trim();
  txt = txt.replace(/^```json\s*/i,'').replace(/\s*```$/,'').trim();
  txt = txt.replace(/^```\s*/,'').replace(/\s*```$/,'').trim();
  const bStart = txt.indexOf('{'); const bEnd = txt.lastIndexOf('}');
  if (bStart !== -1 && bEnd !== -1) txt = txt.substring(bStart, bEnd + 1);
  txt = txt.replace(/[‘’]/g,"'").replace(/[“”«»]/g,'"');
  parsed = JSON.parse(txt);
} catch(e) {
  return technicalError('Repair JSON parse failed: ' + e.message);
}

return [{ json: {
  parse_ok: true,
  parse_method: 'repaired_json',
  repair_used: true,
  repair_status: 'success',
  parse_error: '',
  raw_response_preview: rawPreview,
  ...parsed
}}];

const data = $json;
const srcRecord = $('Normalize Firecrawl Output').first().json;

function clamp(v) { const n = parseInt(v); return isNaN(n) ? 1 : Math.min(100, Math.max(1, n)); }
function truncate(s, n) { return (s == null ? '' : String(s)).substring(0, n); }

// Normalize free-text service_type into allowed enum values
function normalizeServiceType(raw, hay) {
  const allowed = ['secured_auto_loan','secured_real_estate_loan','pts_loan','refinancing','mortgage_adjacent','generic_lending'];
  const r = (raw || '').toLowerCase().trim();
  if (allowed.includes(r)) return r;
  const s = r + ' ' + (hay || '');
  if (s.includes('птс') || s.includes('pts')) return 'pts_loan';
  if ((s.includes('авто') || s.includes('машин')) && (s.includes('залог') || s.includes('collateral') || s.includes('ломбард'))) return 'secured_auto_loan';
  if (s.includes('недвиж') || s.includes('квартир') || s.includes('дом') || s.includes('земл')) return 'secured_real_estate_loan';
  if (s.includes('рефинанс') || s.includes('refinanc')) return 'refinancing';
  if (s.includes('ипотек') || s.includes('mortgage')) return 'mortgage_adjacent';
  if (s.includes('бизнес') || s.includes('business')) {
    if (s.includes('недвиж') || s.includes('квартир')) return 'secured_real_estate_loan';
    return 'generic_lending';
  }
  return 'unknown';
}

// Descriptive company_name fallback for competitors (never invent a brand)
function companyNameFallback(existing, entity, hay) {
  if (existing && String(existing).trim() !== '') return existing;
  if (entity === 'competitor' && (hay.includes('мфо') || hay.includes('микрофинанс') || hay.includes('mfo'))) return 'МФО / частный кредитор';
  if (hay.includes('частный инвестор')) return 'Частный инвестор';
  if (hay.includes('автоломбард')) return 'Автоломбард';
  if (hay.includes('брокер')) return 'Брокер';
  if (entity === 'competitor') return 'Конкурент без бренда';
  return '';
}

// recommended_action normalization driven by final route
function normalizeAction(route, entity, action, leadScore) {
  if (route === 'technical_errors') return 'ignore';
  if (route === 'skipped_log') return 'ignore';
  if (route === 'results' && entity === 'lead_signal') return 'contact';
  if (route === 'review_queue') {
    if (entity === 'lead_signal' && action === 'contact' && leadScore >= 70) return 'contact';
    return 'investigate';
  }
  if (route === 'monitor_queue' && entity === 'competitor') return 'monitor';
  if (route === 'content_queue') {
    if (action === 'contact' || action === 'investigate') return action;
    return 'create_content';
  }
  return action;
}

// Pass-through for confirmed technical_error (from Parse Repaired JSON)
if (data.processing_status === 'technical_error' && data.route === 'technical_errors') {
  return [{ json: {
    created_at: data.created_at || srcRecord.parsed_at || '',
    source_type: data.source_type || srcRecord.source_type || '',
    platform: data.platform || srcRecord.platform || '',
    source_url: data.source_url || srcRecord.source_url || '',
    parsed_at: data.parsed_at || srcRecord.parsed_at || '',
    published_at: data.published_at || srcRecord.published_at || '',
    freshness_status: data.freshness_status || 'unknown',
    entity_type: data.entity_type || 'irrelevant',
    company_name: data.company_name || '',
    profile_name: data.profile_name || '',
    profile_url: data.profile_url || srcRecord.profile_url || '',
    region: data.region || '',
    service_type: data.service_type || 'unknown',
    offer_text: data.offer_text || '',
    terms: data.terms || '',
    contact_public: data.contact_public || '',
    text_context: data.text_context || srcRecord.text_context || '',
    detected_need: data.detected_need || '',
    competitor_strength: clamp(data.competitor_strength),
    lead_signal_score: clamp(data.lead_signal_score),
    content_idea_score: clamp(data.content_idea_score),
    quality_score: clamp(data.quality_score),
    reason: data.reason || '',
    recommended_action: 'ignore',
    status: data.status || 'analyzed',
    processing_status: 'technical_error',
    parse_method: data.parse_method || 'technical_error',
    parse_error: truncate(data.parse_error || '', 800),
    raw_response_preview: truncate(data.raw_response_preview, 500),
    route: 'technical_errors',
    needs_manual_review: true,
    repair_used: data.repair_used || false,
    repair_status: data.repair_status || ''
  }}];
}

// Normalize schema fields
const entity = data.entity_type || 'irrelevant';
const status = data.status || 'analyzed';
const recAction = data.recommended_action || 'ignore';
const leadScore = clamp(data.lead_signal_score);
const compScore = clamp(data.competitor_strength);
const contentScore = clamp(data.content_idea_score);
const qualScore = clamp(data.quality_score);

const validEntities = ['competitor','lead_signal','market_signal','content_idea','irrelevant'];
const validActions = ['monitor','contact','create_content','ignore','investigate'];
const safeEntity = validEntities.includes(entity) ? entity : 'irrelevant';
const safeAction = validActions.includes(recAction) ? recAction : 'ignore';
const safeStatus = (status === 'skipped') ? 'skipped' : 'analyzed';

// Derived text haystacks for normalization and routing keyword checks
const hay = ((data.text_context||'') + ' ' + (data.offer_text||'') + ' ' + (data.detected_need||'') + ' ' + (data.reason||'') + ' ' + (data.service_type||'') + ' ' + (srcRecord.text_context||'')).toLowerCase();
const companyHay = ((data.text_context||'') + ' ' + (data.reason||'') + ' ' + (data.offer_text||'') + ' ' + (data.source_url||srcRecord.source_url||'') + ' ' + (data.detected_need||'')).toLowerCase();

const safeServiceType = normalizeServiceType(data.service_type, hay);
const safeCompanyName = companyNameFallback(data.company_name, safeEntity, companyHay);

// Determine processing_status
let procStatus = 'parsed_success';
if (safeStatus === 'skipped' || safeEntity === 'irrelevant') procStatus = 'business_skip';

// === Post-repair business-consistency hardening (DEC-043 / DEC-044) ===
// Repaired JSON is structurally valid but not trusted for business scores/language.
function _hasCyrillic(s){ return /[\u0400-\u04FF]/.test(s || ''); }
function _hasCJK(s){ return /[\u3400-\u9FFF\uF900-\uFAFF]/.test(s || ''); }

const srcTypeLc = (data.source_type || srcRecord.source_type || '').toLowerCase();
const platformLc = (data.platform || srcRecord.platform || '').toLowerCase();
const isWebsiteScrape = (srcTypeLc === 'scraped_web') && (platformLc === 'website');
const evidence = ((data.text_context||'') + ' ' + (data.offer_text||'') + ' ' + (data.terms||'') + ' ' + (data.reason||'') + ' ' + (srcRecord.text_context||'')).toLowerCase();
const hasParseError = !!(data.parse_error && String(data.parse_error).trim() !== '');
const textUsable = ((srcRecord.text_context || data.text_context || '').trim().length >= 80);

// Competitor signal counting (B)
const signalTerms = ['кредит','займ','залог','птс','авто','недвиж','рефинанс','ипотек','ставка','сумма','одобрен','плохая кредитн','просрочк','телефон','москва','московск'];
let compSignals = 0;
for (const t of signalTerms) { if (evidence.includes(t)) compSignals++; }

// Effective (hardened) values default to the normalized values
let effAction = safeAction;
let effComp = compScore;
let effQual = qualScore;
let effServiceType = safeServiceType;

const isCompetitorWebsite = (safeEntity === 'competitor' && isWebsiteScrape);
const richCompetitor = isCompetitorWebsite && compSignals >= 3;

// B + C: competitor consistency rule (applies even when repaired output under-scored)
if (isCompetitorWebsite && compSignals >= 3) {
  effComp = Math.max(effComp, 65);
  effQual = Math.max(effQual, 65);
  effAction = 'monitor';
}
if (isCompetitorWebsite && compSignals >= 5) {
  effComp = Math.max(effComp, 75);
  effQual = Math.max(effQual, 75);
}
// C: repaired competitor scores are unreliable — never below 45 unless text unusable
if (data.repair_used === true && safeEntity === 'competitor' && textUsable) {
  effComp = Math.max(effComp, 45);
}

// D: multi-product website → generic_lending unless one product dominates
const prodCats = [];
if (evidence.includes('залог') && (evidence.includes('недвиж')||evidence.includes('квартир')||evidence.includes('дом ')||evidence.includes('земл')||evidence.includes('коммерческ'))) prodCats.push('real_estate');
if (evidence.includes('рефинанс')) prodCats.push('refinancing');
if (evidence.includes('ипотек')) prodCats.push('mortgage');
if ((evidence.includes('авто')||evidence.includes('машин')) && (evidence.includes('залог')||evidence.includes('птс')||evidence.includes('pts'))) prodCats.push('auto');
if (isWebsiteScrape && prodCats.length >= 2) {
  effServiceType = 'generic_lending';
}

// A: language guard — Russian source but reason in Chinese / mostly foreign script
function _russianFallbackReason(entity, company, service, terms, region, lead, comp, qual) {
  if (entity === 'competitor') {
    return 'Страница содержит признаки конкурента в нише залогового кредитования: указаны продукты, условия/ставки, регион или контакт. Запись отправлена в мониторинг конкурентов для проверки офферов и условий.';
  }
  const parts = ['Автоматически сформированное описание (исходный reason был не на русском).'];
  parts.push('Тип записи: ' + entity + (company ? ', ' + company : '') + (service && service !== 'unknown' ? ', услуга: ' + service : '') + '.');
  if (region) parts.push('Регион: ' + region + '.');
  if (terms) parts.push('Условия: ' + truncate(terms, 120) + '.');
  parts.push('Оценки — лид: ' + lead + ', конкурент: ' + comp + ', качество: ' + qual + '.');
  return parts.join(' ');
}
let finalReason = data.reason || '';
const srcHasCyrillic = _hasCyrillic(srcRecord.text_context || data.text_context || evidence);
const reasonLetters = (finalReason.match(/[A-Za-z\u0400-\u04FF]/g) || []).length;
const reasonNonSpace = (finalReason.match(/\S/g) || []).length;
const reasonForeign = reasonNonSpace >= 8 && (reasonLetters / reasonNonSpace) < 0.4;
if (srcHasCyrillic && finalReason && (_hasCJK(finalReason) || reasonForeign || (!_hasCyrillic(finalReason) && reasonLetters === 0))) {
  finalReason = _russianFallbackReason(safeEntity, safeCompanyName, effServiceType, data.terms || '', data.region || '', leadScore, effComp, effQual);
}

// Weak / potential lead detection (must run before content_queue routing)
const srcType = (data.source_type || srcRecord.source_type || '').toLowerCase();
const isSocialOrClassified = (srcType === 'social' || srcType === 'classified');
const productTerms = ['loan','collateral','pts','auto','real estate','refinanc','займ','кредит','залог','птс','авто','машин','недвиж','квартир','земл','рефинанс','ипотек'];
const mentionsProduct = productTerms.some(t => hay.includes(t));

const weakLead = (
  (safeEntity === 'lead_signal' && leadScore >= 30 && leadScore <= 69) ||
  (effAction === 'investigate') ||
  (leadScore >= 30 && isSocialOrClassified && mentionsProduct) ||
  (safeEntity === 'content_idea' && leadScore >= 30 && isSocialOrClassified && safeServiceType !== 'unknown')
);

// Routing priority (F, after consistency hardening — DEC-043):
// 1 technical_errors (handled above) 2 skipped/irrelevant 3 hot lead
// 4 rich competitor website (never review_queue, rule C) 5 weak lead
// 6 competitor>=45 7 pure content idea 8 fallback review_queue
let route;
let needsReview;

if (safeStatus === 'skipped' || safeEntity === 'irrelevant') {
  route = 'skipped_log'; needsReview = false;
} else if (safeEntity === 'lead_signal' && leadScore >= 70 && effAction === 'contact') {
  route = 'results'; needsReview = false;
} else if (richCompetitor) {
  route = 'monitor_queue'; needsReview = hasParseError;
} else if (weakLead) {
  route = 'review_queue'; needsReview = true;
} else if (safeEntity === 'competitor' && effComp >= 45) {
  route = 'monitor_queue'; needsReview = false;
} else if (safeEntity === 'content_idea' && contentScore >= 50) {
  route = 'content_queue'; needsReview = true;
} else {
  route = 'review_queue'; needsReview = true;
}

// Safety: enforce route is exactly one of the six valid sheet tabs
const validRoutes = ['results','review_queue','monitor_queue','content_queue','skipped_log','technical_errors'];
let parseError = data.parse_error || '';
if (!validRoutes.includes(route)) {
  route = 'technical_errors';
  procStatus = 'technical_error';
  needsReview = true;
  parseError = (parseError ? parseError + '; ' : '') + 'invalid_route';
}

// Final recommended_action consistent with the route
const finalAction = normalizeAction(route, safeEntity, effAction, leadScore);

// v0.1 dedup hint: source_url is the first dedup key. Real scraper workflow
// should check existing source_url in the target tab before append. No dedup
// column is emitted yet (see DEC-037 / TABLE_SCHEMA notes).

return [{ json: {
  created_at: data.created_at || srcRecord.parsed_at || '',
  source_type: data.source_type || srcRecord.source_type || '',
  platform: data.platform || srcRecord.platform || '',
  source_url: data.source_url || srcRecord.source_url || '',
  parsed_at: data.parsed_at || srcRecord.parsed_at || '',
  published_at: data.published_at || srcRecord.published_at || '',
  freshness_status: data.freshness_status || 'unknown',
  entity_type: safeEntity,
  company_name: safeCompanyName,
  profile_name: data.profile_name || '',
  profile_url: data.profile_url || srcRecord.profile_url || '',
  region: data.region || '',
  service_type: effServiceType,
  offer_text: data.offer_text || '',
  terms: data.terms || '',
  contact_public: data.contact_public || '',
  text_context: data.text_context || '',
  detected_need: data.detected_need || '',
  competitor_strength: effComp,
  lead_signal_score: leadScore,
  content_idea_score: contentScore,
  quality_score: effQual,
